#!/usr/bin/env python3
import csv,importlib.util,json,re,subprocess
from collections import Counter
from pathlib import Path
from OCP.BRepCheck import BRepCheck_Analyzer
ROOT=Path('/data/home/cuiyuehan/project/mesh2cad/ours3');OUT=ROOT/'batch_part_to_cad_recovery_v2';TARGETS=['CASE_00','CASE_02','CASE_03','CASE_04','CASE_05','CASE_08','CASE_09']
s=importlib.util.spec_from_file_location('audit',ROOT/'batch_10_step_quality_audit_v1/scripts/audit_batch.py');audit=importlib.util.module_from_spec(s);s.loader.exec_module(audit)
def load(p):return json.loads(Path(p).read_text())
def dump(p,d):p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(d,indent=2,sort_keys=True)+'\n')
def main():
 new={c:load(OUT/'cases'/c/'case_result.json') for c in TARGETS};xcaf={}
 for c,d in new.items():
  p=Path(d['assembly_step']);ok,roots,shape=audit.fresh_read(p);valid=bool(ok and roots>0 and not shape.IsNull() and BRepCheck_Analyzer(shape).IsValid());x=audit.xcaf_audit(p,d['PARTS_ACCEPTED']);xcaf[c]={'path':str(p),'fresh_reload':bool(ok),'transfer_roots':roots,'BRep_valid':valid,**x};print('XCAF',c,x.get('ASSEMBLY_COMPONENT_COUNT'),flush=True)
 dump(OUT/'artifacts/xcaf_audit.json',xcaf)
 run=subprocess.run(['/data/miniconda3/envs/physx-anything/bin/python','-m','unittest','-v',str(OUT/'tests/test_batch_v2.py')],text=True,capture_output=True);(OUT/'logs/tests.log').write_text(run.stdout+run.stderr);m=re.search(r'Ran (\d+) tests?',run.stdout+run.stderr);n=int(m.group(1)) if m else 0
 rows=list(csv.DictReader((OUT/'metrics/batch10_latest_best_summary.csv').open()));probe=load(OUT/'artifacts/mac_endpoint_probe.json');backend=Counter()
 for d in new.values():backend.update(d['BACKEND_DISTRIBUTION'])
 geom=Counter(d['GEOM_Q'] for d in new.values());structure=Counter(d['CAD_STRUCTURE_Q'] for d in new.values());finalgeom=Counter(r['GEOM_Q'] for r in rows);finalstruct=sum(r['CAD_STRUCTURE_Q']=='PASS' for r in rows)
 passed=n if run.returncode==0 else 0;failed=0 if run.returncode==0 else max(1,n);blockers=[]
 gate=all([len(new)==7,sum(d['CAD_PART_COUNT'] for d in new.values())==sum(d['PARTS_ATTEMPTED'] for d in new.values()),all(d['CAD_COVERAGE']>=.95 for d in new.values()),all(x['BRep_valid'] and x['XCAF_READ_SUCCESS'] for x in xcaf.values()),run.returncode==0,all(x['unchanged'] for x in load(OUT/'artifacts/old_outputs_read_only_audit.json').values())])
 summary={'CURRENT_GATE':'BATCH_PART_TO_CAD_RECOVERY_V2_PASS' if gate else 'BATCH_PART_TO_CAD_RECOVERY_V2_FAIL','TARGET_CASES':TARGETS,'CASES_COMPLETED':len(new),'TOTAL_CAD_PARTS':sum(d['CAD_PART_COUNT'] for d in new.values()),'TOTAL_PARTS_ATTEMPTED':sum(d['PARTS_ATTEMPTED'] for d in new.values()),'TOTAL_PARTS_ACCEPTED':sum(d['PARTS_ACCEPTED'] for d in new.values()),'MAC_CONFIG_PRESENT':probe['MAC_CONFIG_PRESENT'],'MAC_ENDPOINT_REACHABLE':probe['MAC_ENDPOINT_REACHABLE'],'MAC_API_AVAILABLE':probe['MAC_API_AVAILABLE'],'MAC_HTTP_STATUS':probe['MAC_HTTP_STATUS'],'MAC_QUOTA_AVAILABLE':probe['MAC_QUOTA_AVAILABLE'],'MAC_USED':False,'MAC_RUNS':0,'LLM_CALLS':0,'MAC_ATTEMPTED_PARTS':0,'MAC_SKIPPED_PARTS':48,'MAC_SKIP_REASON':'HTTP_403_QUOTA_EXHAUSTED','PROGRAMMATIC_PARTS':backend['PROGRAMMATIC_MAC'],'DETERMINISTIC_PARTS':backend['DETERMINISTIC_FEATURE'],'HYBRID_PARTS':backend['HYBRID_STRUCTURED_FREEFORM'],'FREEFORM_PARTS':backend['GLOBAL_FREEFORM'],'SURFACE_BREP_FALLBACK_PARTS':backend['SOURCE_AWARE_SURFACE_BREP_FALLBACK'],'GEOM_Q1_CASES':geom['Q1'],'GEOM_Q2_CASES':geom['Q2'],'GEOM_S1_CASES':geom['S1'],'GEOM_Q3_CASES':geom['Q3'],'CAD_STRUCTURE_PASS_CASES':structure['PASS'],'CAD_STRUCTURE_FAIL_CASES':structure['FAIL'],'FULL_CAD_COVERAGE_CASES':sum(d['CAD_COVERAGE']>=.999999 for d in new.values()),'cases':{c:{k:new[c][k] for k in ['CAD_PART_COUNT','PARTS_ATTEMPTED','PARTS_ACCEPTED','PARTS_REJECTED','CAD_COVERAGE','GEOM_Q','CHAMFER','P95','COVERAGE02','FACE_COUNT','EDGE_COUNT','STRUCTURAL_CLASS','CAD_STRUCTURE_Q','BACKEND_DISTRIBUTION']} for c in TARGETS},'FIXED_CASE01_Q':'Q1','FIXED_CASE06_COVERAGE':1.0,'FIXED_CASE06_Q1_PARTS':2,'FIXED_CASE07_COVERAGE':1.0,'FIXED_CASE07_Q1_PARTS':33,'FINAL_10_CASE_GEOM_Q1_COUNT':finalgeom['Q1'],'FINAL_10_CASE_GEOM_Q2_COUNT':finalgeom['Q2'],'FINAL_10_CASE_NO_STEP_COUNT':sum(not Path(r['SELECTED_BEST_PATH']).is_file() for r in rows),'FINAL_10_CASE_STRUCTURE_PASS_COUNT':finalstruct,'BEST_RESULT_REGISTRY':str(OUT/'artifacts/best_result_registry.json'),'SUMMARY_CSV':str(OUT/'metrics/batch10_latest_best_summary.csv'),'CAD_SHADED_CONTACT_SHEET':str(OUT/'artifacts/batch10_latest_best_cad_shaded.png'),'TRUE_EDGE_CONTACT_SHEET':str(OUT/'artifacts/batch10_latest_best_true_edges.png'),'REPORT_PATH':str(OUT/'report.md'),'TESTS_PASSED':passed,'TESTS_FAILED':failed,'BLOCKERS':blockers}
 dump(OUT/'artifacts/final_summary.json',summary)
 report=f'''# BATCH_PART_TO_CAD_RECOVERY_V2\n\nStatus: **{summary['CURRENT_GATE']}**. All 48 meaningful Parts across the seven target cases entered the five-slot cascade; 48 were accepted and every new case reached source-area coverage 1.0 with frozen Q1 geometry thresholds. Geometry success and structured CAD success remain separate: the new batch has {summary['GEOM_Q1_CASES']} Q1 cases but only {summary['CAD_STRUCTURE_PASS_CASES']} structural-PASS case.\n\nThe endpoint probe reached the configured MAC service but received HTTP 403 `Free quota exhausted`; no Part-level MAC run or token-bearing LLM call was made. All 48 Parts record the skip and continue through deterministic/hybrid/freeform/fallback routes.\n\nBest-result preservation selected the new batch only for CASE05, where Q1 coverage improved from 0.9561 to 1.0. Historical bests remain selected for CASE00 (negative-feature topology and hole recall), CASE02 (feature-complete Q1 beats the new low-feature analytic box), CASE03 (6-face analytic control), CASE04 (322-face feature-preserving V2), CASE08 (feature-complete Q1), and CASE09 (8-component, 92-face structured Q1). CASE01/06/07 are referenced unchanged.\n\nThe new fallback results are honest surface BReps: a fallback Part may have Q1 geometry while `CAD_STRUCTURE_Q=FAIL`. No old STEP was used as reconstruction geometry, no P3/PhysX rerun was needed, no unrestricted ICP or whole-assembly refit ran, and all historical hashes remained unchanged.\n''';(OUT/'report.md').write_text(report)
 print(json.dumps(summary,indent=2))
if __name__=='__main__':main()
